select 1 from(select distinct cabd.prod_id,cabd.asset_id from CHB_ASSETS_BASIS_DATA_NOBTM cabd union all select distinct cabd.prod_id,cbap.asset_code from CHB_ASSETS_BASIS_DATA_NOBTM cabd left join(select distinct cbap.plan_asset_id as plan_asset_id,cbap.asset_code from chb_bot_ast_pos cbap) cbap on cabd.asset_id=cbap.plan_asset_id )cabds LEFT JOIN DATA_AUTH_NOTIFY_INST DA ON cabds.prod_id=dA.business_id and dA.model_type = '02' and DA.DATA_TYPE='PTL01' where 1=1 and ASSETINFO.ASSET_CODE=cabds.asset_id
