/***场外期权类交易连接交易汇总表数据查找所属机构**/
left join ( select distinct cabd.prod_id,cabd.asset_id from CHB_ASSETS_BASIS_DATA cabd union all select distinct cabd.prod_id,cbap.asset_code from CHB_ASSETS_BASIS_DATA cabd left join(select distinct cbap.plan_asset_id as plan_asset_id,cbap.asset_code from chb_bot_ast_pos cbap) cbap on cabd.asset_id=cbap.plan_asset_id )cabds on ASSETINFO.ASSET_CODE=cabds.asset_id
left join (select distinct cabd.prod_id,cabd.asset_id from CHB_ASSETS_BASIS_DATA_NOBTM cabd union all select distinct cabd.prod_id,cbap.asset_code from CHB_ASSETS_BASIS_DATA_NOBTM cabd left join(select distinct cbap.plan_asset_id as plan_asset_id,cbap.asset_code from chb_bot_ast_pos cbap) cbap on cabd.asset_id=cbap.plan_asset_id )cabds on ASSETINFO.ASSET_CODE=cabds.asset_id
LEFT JOIN (SELECT D.BUSINESS_ID,D.BELONG_INSTITUTION_CODE,D.DATA_TYPE FROM DATA_AUTH_NOTIFY_INST D WHERE D.MODEL_TYPE = '02' GROUP BY D.BUSINESS_ID,D.BELONG_INSTITUTION_CODE,D.DATA_TYPE) DA ON (substr(DA.BUSINESS_ID,5) = ASSETINFO.ASSET_CODE) or (DA.BUSINESS_ID = cabds.prod_id) LEFT JOIN CHB_ORG_REGIST_BANK_CODE CC ON da.BELONG_INSTITUTION_CODE=cc.org_code LEFT JOIN CHB_ASSET_SUB_STATUS CS ON ASSETINFO.REGIST_SEQNO=CS.REGIST_SEQNO AND DA.BELONG_INSTITUTION_CODE=CS.INSTITUTION_CODE AND CS.ASSET_TYPE='01'
1=1 /***用金融标的表的交易场所字段来区分是否是公共资产还是私有资产 leipeng 20200711**/
and (ASSETINFO.asset_type not in ('03','06','15') or ASSETINFO.asset_type is null or ASSETINFO.asset_type2 in ('1301') )
#{code,jdbcType=VARCHAR}
#{assetType,jdbcType=VARCHAR}
#{items,jdbcType=CHAR}
#{assetType,jdbcType=VARCHAR}
#{assetTypeTwo,jdbcType=VARCHAR}
and ASSETINFO.ASSET_CODE like concat(concat('%',#{assetCode,jdbcType=VARCHAR}),'%')
AND to_char(ASSETINFO.SUBMIT_TIME, 'yyyy-MM-dd') >= #{sendDateStr,jdbcType=VARCHAR}
AND to_char(ASSETINFO.SUBMIT_TIME, 'yyyy-MM-dd') <= #{sendDateEnd,jdbcType=VARCHAR}
#{tradeMarket,jdbcType=VARCHAR}
AND ASSETINFO.CCY = #{ccy,jdbcType=VARCHAR}
AND to_char(ASSETINFO.STATUS_DATE, 'yyyy-MM-dd') >= #{statusDateStr,jdbcType=VARCHAR}
AND to_char(ASSETINFO.STATUS_DATE, 'yyyy-MM-dd') <= #{statusDateEnd,jdbcType=VARCHAR}
and(
#{submitStatus,jdbcType=VARCHAR}
or CS.SEND_STATUS IS NULL
)
#{submitFeedbackStatus,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
and to_char(ASSETINFO.CHB_SUBMIT_DEADLINE,'yyyy-MM-dd') >= #{submitDeadLineStart,jdbcType=VARCHAR}
and to_char(ASSETINFO.CHB_SUBMIT_DEADLINE,'yyyy-MM-dd') <= #{submitDeadLineEnd,jdbcType=VARCHAR}
and to_char(ASSETINFO.VDATE,'yyyy-MM-dd') >= #{vDateStart,jdbcType=VARCHAR}
and to_char(ASSETINFO.VDATE,'yyyy-MM-dd') <= #{vDateEnd,jdbcType=VARCHAR}
and to_char(ASSETINFO.MDATE,'yyyy-MM-dd') >= #{mDateStart,jdbcType=VARCHAR}
and to_char(ASSETINFO.MDATE,'yyyy-MM-dd') <= #{mDateEnd,jdbcType=VARCHAR}
) order by STATUSDATE desc)

