'02' model_type from CHB_ASSET_INFO_SUB ASSETINFO
LEFT JOIN CHB_ASSET_SUB_STATUS CS ON ASSETINFO.REGIST_SEQNO=CS.REGIST_SEQNO AND CS.ASSET_TYPE='01'
#{code,jdbcType=VARCHAR}
1=1 /***用金融标的表的交易场所字段来区分是否是公共资产还是私有资产 leipeng 20200711**/
and ASSETINFO.asset_type in ('03','06','15') and ASSETINFO.asset_type2 not in ('1301')
/**产品投资交易数据筛选产品交易数据*/ and EXISTS (
select 1 from(select distinct cabd.prod_id,cabd.asset_id from CHB_ASSETS_BASIS_DATA cabd)cabds left join(select distinct cbap.plan_asset_id as plan_asset_id,cbap.asset_code from chb_bot_ast_pos cbap) cbap on cabds.asset_id=cbap.plan_asset_id LEFT JOIN DATA_AUTH_NOTIFY_INST DA ON cabds.prod_id=dA.business_id and dA.model_type = '02' and DA.DATA_TYPE='PTL01' where 1=1 and (ASSETINFO.ASSET_CODE=cabds.asset_id or ASSETINFO.ASSET_CODE=cbap.asset_code)
#{code,jdbcType=VARCHAR}
select 1 from(select distinct cabd.prod_id,cabd.asset_id from CHB_ASSETS_BASIS_DATA_NOBTM cabd union all select distinct cabd.prod_id,cbap.asset_code from CHB_ASSETS_BASIS_DATA_NOBTM cabd left join(select distinct cbap.plan_asset_id as plan_asset_id,cbap.asset_code from chb_bot_ast_pos cbap) cbap on cabd.asset_id=cbap.plan_asset_id )cabds LEFT JOIN DATA_AUTH_NOTIFY_INST DA ON cabds.prod_id=dA.business_id and dA.model_type = '02' and DA.DATA_TYPE='PTL01' where 1=1 and ASSETINFO.ASSET_CODE=cabds.asset_id
#{code,jdbcType=VARCHAR}
union all select 1 from RSK_VALTBL_PRT_BOTASSET_MAP r LEFT JOIN DATA_AUTH_NOTIFY_INST DA ON r.ptl_id=dA.business_id and dA.model_type = '02' WHERE ASSETINFO.ASSET_CODE=substr(r.finprod_id,5)
#{code,jdbcType=VARCHAR}
)
